  ctx.fill();

  // Inner edge
  ctx.fillStyle = '#1a1a2e';
  ctx.beginPath();
  ctx.arc(record.x, record.y, record.diameter / 4, 0, Math.PI * 2);
  ctx.fill();

  // Center hole
  ctx.fillStyle = '#1a1a2e';
  ctx.beginPath();
  ctx.arc(record.x, record.y, record.diameter / 8, 0, Math.PI * 2);
  ctx.fill();
});

// Draw grooves
ctx.strokeStyle = '#5a5a7e';
ctx.lineWidth = 1;
for (let i = 0; i < records.length; i++) {
  const record = records[i];
  const radius = record.diameter / 2;

  // Vertical groove
  ctx.beginPath();
  ctx.moveTo(record.x, record.y - radius);
  ctx.lineTo(record.x, record.y + radius);
  ctx.stroke();

  // Horizontal groove
  ctx.beginPath();
  ctx.moveTo(record.x - radius, record.y);
  ctx.lineTo(record.x + radius, record.y);
  ctx.stroke();
}

