// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Define colors
const colors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#Feca57', '#EFD8DC'];

// Draw circles with alternating colors
for (let i = 0; i < 6; i++) {
    const radius = maxRadius - i * 30;
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
    ctx.strokeStyle = colors[i % 6];
    ctx.lineWidth = 3;
    ctx.stroke();
}

// Draw radial patterns
for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * Math.PI * 2;
    const x = centerX + Math.cos(angle) * (maxRadius - 20);
    const y = centerY + Math.sin(angle) * (maxRadius - 20);

    // Draw triangles
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(x, y);
    ctx.lineTo(centerX + Math.cos(angle + Math.PI/3) * (maxRadius - 20),
               centerY + Math.sin(angle + Math.PI/3) * (maxRadius - 20));
    ctx.closePath();
    ctx.fillStyle = colors[i % 6];
    ctx.fill();

    // Draw squares
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(x, y);
    ctx.lineTo(centerX + Math.cos(angle + Math.PI/3) * (maxRadius - 20),
               centerY + Math.sin(angle + Math.PI/3) * (maxRadius - 20));
    ctx.lineTo(centerX + Math.cos(angle + Math.PI/6) * (maxRadius - 20),
               centerY + Math.sin(angle + Math.PI/6) * (maxRadius - 20));
    ctx.closePath();
    ctx.fillStyle = colors[(i + 1) % 6];
    ctx.fill();
}

// Draw center pattern
