ctx.moveTo(centerX, centerY);
ctx.lineTo(centerX + 10, centerY - 10);
ctx.lineTo(centerX - 10, centerY - 10);
ctx.closePath();
ctx.fillStyle = '#4ECDC4';
ctx.fill();

// Draw cool tones fractal spiral
ctx.fillStyle = '#0a0a2a';
ctx.fillRect(0, 0, W, H);

const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

function drawSpiral(radius, angle, depth) {
    if (depth > 0) {
        ctx.save();
        ctx.translate(centerX, centerY);
        ctx.rotate(angle);

        // Draw spiral segment
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(radius, 0);
        ctx.strokeStyle = `hsl(${120 + depth * 3}, 80%, ${80 - depth * 10}%)`;
        ctx.lineWidth = 2;
        ctx.stroke();

        // Recursive calls for next segments
        drawSpiral(radius * 1.1, angle + 0.3, depth - 1);
        drawSpiral(radius * 1.1, angle - 0.3, depth - 1);

        ctx.restore();
    }
}

